window.NIKOTIAN_NEW_PIANOS = [{"id":"new-04","slug":"bluthner-model-a-professional-upright-124","url":"/pianos/new/bluthner-model-a-professional-upright-124/","detailPage":"piano.html?model=bluthner-model-a-professional-upright-124","manufacturer":"Blüthner","manufacturerSlug":"bluthner","model":"Model A Professional Upright 124","type":"upright","typeLabel":"Όρθιο πιάνο","category":"Κλασικό πιάνο","sizeCm":124,"description":["Η πλάτη ενισχύεται σε πέντε σημεία βεβαιώνοντας έτσι την υψηλή σταθερότητα και την πρόσθετη υποστήριξη για την ένταση που δημιουργείται από τις χορδές.","Η ευαισθησία του ηχείου αποκρίνεται στο πιανίστα για να δημιουργήσει την επιθυμητή δυναμική και τον τόνο, που εκπληρώνουν το ρόλο του επαγγελματικού όρθιου."],"additional":["Κλασικό πιάνο"],"facts":[],"drawing":[],"finishes":[],"specModel":null,"specs":[],"images":[{"src":"assets/photos/pianos/new/bluthner-model-a-professional-upright-124.jpg","width":400,"height":357,"alt":"Blüthner Model A Professional Upright 124, όρθιο πιάνο, σε ουδέτερο φόντο","sourceSize":[400,357]}],"pdf":null,"order":1,"name":"Blüthner Model A Professional Upright 124","summary":["Η πλάτη του ενισχύεται σε πέντε σημεία, για υψηλή σταθερότητα και πρόσθετη στήριξη απέναντι στην τάση των χορδών.","Το ευαίσθητο ηχείο ανταποκρίνεται στον πιανίστα και αποδίδει τη δυναμική και τον τόνο που περιμένει κανείς από ένα επαγγελματικό όρθιο πιάνο."],"availability":"order","availabilityLabel":"Κατόπιν παραγγελίας"},{"id":"new-03","slug":"bluthner-model-b-professional-concert-upright-132","url":"/pianos/new/bluthner-model-b-professional-concert-upright-132/","detailPage":"piano.html?model=bluthner-model-b-professional-concert-upright-132","manufacturer":"Blüthner","manufacturerSlug":"bluthner","model":"Model B Professional Concert Upright 132","type":"upright","typeLabel":"Όρθιο πιάνο","category":"Κλασικό πιάνο","sizeCm":132,"description":["Ένα επίτευγμα της μουσικής και της τεχνολογίας! Προσφέρει έναν εντυπωσιακό ήχο, πλούσιο και θερμό με έναν μελωδικό τόνο και γρήγορη επαναφορά."],"additional":["Κλασικό πιάνο"],"facts":[],"drawing":[],"finishes":[],"specModel":null,"specs":[],"images":[{"src":"assets/photos/pianos/new/bluthner-model-b-professional-concert-upright-132.jpg","width":400,"height":370,"alt":"Blüthner Model B Professional Concert Upright 132, όρθιο πιάνο, σε ουδέτερο φόντο","sourceSize":[400,370]}],"pdf":null,"order":2,"name":"Blüthner Model B Professional Concert Upright 132","summary":["Ένα επίτευγμα μουσικής και τεχνολογίας: ήχος εντυπωσιακός, πλούσιος και θερμός, με μελωδικό τόνο και γρήγορη επαναφορά."],"availability":"order","availabilityLabel":"Κατόπιν παραγγελίας"},{"id":"new-02","slug":"bluthner-model-6-salon-grand-191","url":"/pianos/new/bluthner-model-6-salon-grand-191/","detailPage":"piano.html?model=bluthner-model-6-salon-grand-191","manufacturer":"Blüthner","manufacturerSlug":"bluthner","model":"Model 6 Salon Grand 191","type":"grand","typeLabel":"Πιάνο με ουρά","category":"Κλασικό πιάνο","sizeCm":191,"description":["Το Salon Grand προσφέρει ένα υγιή ποσοστό διαστάσεων και δυναμικής. Αυτό το όργανο προσφέρει τις περιεκτικές δυνατότητες της καλλιτεχνικής απόδοσης μουσικής και ικανοποιεί τα αιτήματα των επαγγελματιών. Οι τονικές του ιδιότητες είναι που το κάνουν ένα όργανο συναυλίας κατάλληλο για σόλο ρεσιτάλ ή συμπληρωματικό σε μικρές ορχήστρες ή ακόμα και σε ένα μεγάλο σαλόνι ενός σπιτιού. Η ανταπόκριση του που συνδυάζεται με το δονούμενο τονικό χαρακτήρα θα σας αφήσει εξ ολοκλήρου ικανοποιημένους."],"additional":["Κλασικό πιάνο"],"facts":[],"drawing":[],"finishes":[],"specModel":null,"specs":[],"images":[{"src":"assets/photos/pianos/new/bluthner-model-6-salon-grand-191.jpg","width":400,"height":443,"alt":"Blüthner Model 6 Salon Grand 191, πιάνο με ουρά, σε ουδέτερο φόντο","sourceSize":[400,443]}],"pdf":null,"order":3,"name":"Blüthner Model 6 Salon Grand 191","summary":["Το Salon Grand προσφέρει μια ισορροπημένη σχέση διαστάσεων και δυναμικής."],"body":["Διαθέτει τις πλήρεις δυνατότητες καλλιτεχνικής απόδοσης που ζητούν οι επαγγελματίες. Οι τονικές του ιδιότητες το κάνουν όργανο συναυλίας κατάλληλο για σόλο ρεσιτάλ, για συνεργασία με μικρές ορχήστρες ή ακόμη και για το μεγάλο σαλόνι ενός σπιτιού.","Η ανταπόκρισή του, σε συνδυασμό με τον ζωντανό τονικό του χαρακτήρα, αφήνει τον πιανίστα απόλυτα ικανοποιημένο."],"availability":"order","availabilityLabel":"Κατόπιν παραγγελίας"},{"id":"new-06","slug":"grotrian-steinweg-classic-124","url":"/pianos/new/grotrian-steinweg-classic-124/","detailPage":"piano.html?model=grotrian-steinweg-classic-124","manufacturer":"Grotrian Steinweg","manufacturerSlug":"grotrian-steinweg","model":"Classic 124","type":"upright","typeLabel":"Όρθιο πιάνο","category":"Κλασικό πιάνο","sizeCm":124,"description":["Το μοντέλο classic της Grotrian εγγυάται δεκαετίες μουσικής ευχαρίστησης. Και θα είναι ακόμα εκεί για να το απολαύσουν και οι μελλοντικές γενιές. Ένα πραγματικά διαχρονικό πιάνο."],"additional":["Κλασικό πιάνο","Μέγεθος: 124 x 148 x 57"],"facts":[{"label":"Μέγεθος","value":"124 x 148 x 57"}],"drawing":[],"finishes":[],"specModel":null,"specs":[{"label":"Τύπος","value":"Όρθιο πιάνο"},{"label":"Διαστάσεις","value":"124 × 148 × 57 cm"},{"label":"Βάρος","value":"255 kg"}],"images":[{"src":"assets/photos/pianos/new/grotrian-steinweg-classic-124.jpg","width":326,"height":337,"alt":"Grotrian Steinweg Classic 124, όρθιο πιάνο, σε ουδέτερο φόντο","sourceSize":[400,350],"large":{"src":"assets/photos/pianos/new/grotrian-steinweg-classic-124-large.jpg","width":1400,"height":1449,"alt":"Grotrian Steinweg Classic 124, όρθιο πιάνο σε μαύρο γυαλιστερό φινίρισμα","fit":"contain","sourceSize":[1703,1654]}}],"pdf":{"src":"assets/docs/pianos/new/grotrian-steinweg-classic-124.pdf","label":"Φυλλάδιο κατασκευαστή","language":"Γερμανικά, αγγλικά, γαλλικά","bytes":782751},"order":4,"name":"Grotrian Steinweg Classic 124","summary":["Το Classic της Grotrian είναι φτιαγμένο για δεκαετίες μουσικής χαράς — και θα είναι ακόμη εκεί για τις επόμενες γενιές. Ένα πραγματικά διαχρονικό πιάνο."],"body":["Σύμφωνα με τον κατασκευαστή, ο ήχος του Classic είναι καθαρός και λεπτοδουλεμένος — σχεδόν σμιλεμένος — και ταυτόχρονα εξαιρετικά ευέλικτος.","Ανταποκρίνεται εξίσου στο εκφραστικό και στο δεξιοτεχνικό παίξιμο, με έναν ήχο που πείθει όχι μόνο εκείνον που παίζει, αλλά και όσους ακούν."],"gallery":[{"src":"assets/photos/pianos/new/grotrian-steinweg-classic-124-detail.jpg","width":1600,"height":1080,"alt":"Κοντινό στα σφυριά του μηχανισμού, από το φυλλάδιο του Classic","fit":"cover","role":"gallery","sourceSize":[3828,2585]}],"availability":"order","availabilityLabel":"Κατόπιν παραγγελίας"},{"id":"new-07","slug":"grotrian-steinweg-concertino-132","url":"/pianos/new/grotrian-steinweg-concertino-132/","detailPage":"piano.html?model=grotrian-steinweg-concertino-132","manufacturer":"Grotrian Steinweg","manufacturerSlug":"grotrian-steinweg","model":"Concertino 132","type":"upright","typeLabel":"Όρθιο πιάνο","category":"Κλασικό πιάνο","sizeCm":132,"description":["Όταν παίζετε στο Concertino, θα νοιώσετε πως είστε το κεντρικό σημείο της παράστασης. Είναι το ιδανικό όργανο για την έκφραση των μεγάλων συναισθημάτων."],"additional":["Κλασικό πιάνο"],"facts":[],"drawing":[],"finishes":[],"specModel":null,"specs":[{"label":"Τύπος","value":"Όρθιο πιάνο"},{"label":"Διαστάσεις","value":"132 × 157 × 66 cm"},{"label":"Βάρος","value":"295 kg"}],"images":[{"src":"assets/photos/pianos/new/grotrian-steinweg-concertino-132.jpg","width":335,"height":341,"alt":"Grotrian Steinweg Concertino 132, όρθιο πιάνο, σε ουδέτερο φόντο","sourceSize":[400,350],"large":{"src":"assets/photos/pianos/new/grotrian-steinweg-concertino-132-large.jpg","width":1400,"height":1431,"alt":"Grotrian Steinweg Concertino 132, όρθιο πιάνο σε μαύρο γυαλιστερό φινίρισμα","fit":"contain","sourceSize":[1696,1651]}}],"pdf":{"src":"assets/docs/pianos/new/grotrian-steinweg-concertino-132.pdf","label":"Φυλλάδιο κατασκευαστή","language":"Γερμανικά, αγγλικά, γαλλικά","bytes":664284},"order":5,"name":"Grotrian Steinweg Concertino 132","summary":["Όταν παίζετε στο Concertino, νιώθετε πως βρίσκεστε στο επίκεντρο της παράστασης. Είναι το ιδανικό όργανο για την έκφραση μεγάλων συναισθημάτων."],"body":["Όπως το περιγράφει ο κατασκευαστής: βλέπετε ένα όρθιο πιάνο και ακούτε ένα πιάνο με ουρά. Ο ήχος του θυμίζει περισσότερο πιάνο με ουρά σαλονιού παρά ένα συνηθισμένο όρθιο — αποτέλεσμα μακράς παράδοσης και συνεχούς εξέλιξης στην κατασκευή πιάνων."],"gallery":[{"src":"assets/photos/pianos/new/grotrian-steinweg-concertino-132-detail.jpg","width":1600,"height":1081,"alt":"Κοντινό στα σφυριά του μηχανισμού, από το φυλλάδιο του Concertino","fit":"cover","role":"gallery","sourceSize":[3718,2512]}],"availability":"order","availabilityLabel":"Κατόπιν παραγγελίας"},{"id":"new-08","slug":"grotrian-steinweg-chambre-165","url":"/pianos/new/grotrian-steinweg-chambre-165/","detailPage":"piano.html?model=grotrian-steinweg-chambre-165","manufacturer":"Grotrian Steinweg","manufacturerSlug":"grotrian-steinweg","model":"Chambre 165","type":"grand","typeLabel":"Πιάνο με ουρά","category":"Κλασικό πιάνο","sizeCm":165,"description":["To Chambre εκπλήσει εξερευνώντας τα όρια των ακουστικών του επιδόσεων. Προσφέρεται σε μια σειρά χρωμάτων που μπορούν να μετασχηματίσουν το καθιστικό σας σε μια αίθουσα συναυλιών."],"additional":["Κλασικό πιάνο"],"facts":[],"drawing":[],"finishes":[],"specModel":null,"specs":[{"label":"Τύπος","value":"Πιάνο με ουρά"},{"label":"Διαστάσεις","value":"165 × 150 × 100 cm"},{"label":"Βάρος","value":"290 kg"},{"label":"Τάση χορδών","value":"περίπου 18 τόνοι"}],"images":[{"src":"assets/photos/pianos/new/grotrian-steinweg-chambre-165.jpg","width":281,"height":346,"alt":"Grotrian Steinweg Chambre 165, πιάνο με ουρά, σε ουδέτερο φόντο","sourceSize":[400,350],"large":{"src":"assets/photos/pianos/new/grotrian-steinweg-chambre-165-large.jpg","width":1349,"height":1653,"alt":"Grotrian Steinweg Chambre 165, πιάνο με ουρά σε μαύρο γυαλιστερό φινίρισμα","fit":"contain","sourceSize":[1766,1688]}}],"pdf":{"src":"assets/docs/pianos/new/grotrian-steinweg-chambre-165.pdf","label":"Φυλλάδιο κατασκευαστή","language":"Γερμανικά, αγγλικά, γαλλικά","bytes":405604},"order":6,"name":"Grotrian Steinweg Chambre 165","summary":["Το Chambre εντυπωσιάζει εξερευνώντας τα όρια των ακουστικών του δυνατοτήτων. Προσφέρεται σε σειρά χρωμάτων και μπορεί να μετατρέψει το καθιστικό σας σε αίθουσα συναυλιών."],"body":["Σύμφωνα με τον κατασκευαστή, οι χορδές του δέχονται συνολική τάση περίπου 18 τόνων. Χάρη στον προσεκτικά ρυθμισμένο μηχανισμό, ακόμη και το πιο ανάλαφρο άγγιγμα αποδίδει καθαρό τόνο με εντυπωσιακό όγκο — ιδανικό για προσωπικές συναυλίες στο σπίτι."],"gallery":[{"src":"assets/photos/pianos/new/grotrian-steinweg-chambre-165-detail.jpg","width":1600,"height":1081,"alt":"Κοντινό στο εσωτερικό του πιάνου, από το φυλλάδιο του Chambre","fit":"cover","role":"gallery","sourceSize":[2603,1759]}],"availability":"order","availabilityLabel":"Κατόπιν παραγγελίας"},{"id":"new-09","slug":"grotrian-steinweg-cabinet-192","url":"/pianos/new/grotrian-steinweg-cabinet-192/","detailPage":"piano.html?model=grotrian-steinweg-cabinet-192","manufacturer":"Grotrian Steinweg","manufacturerSlug":"grotrian-steinweg","model":"Cabinet 192","type":"grand","typeLabel":"Πιάνο με ουρά","category":"Κλασικό πιάνο","sizeCm":192,"description":["Κάθε μοντέλο Cabinet έχει το μυστικό του.","Όσο περνάνε τα χρόνια διαμορφώνουν τον αλάνθητο χαρακτήρα τους και την αυθεντική τους προσωπικότητα. Και πάντα θα παραμένουν Grotrian."],"additional":["Κλασικό πιάνο"],"facts":[],"drawing":[],"finishes":[],"specModel":null,"specs":[{"label":"Τύπος","value":"Πιάνο με ουρά"},{"label":"Διαστάσεις","value":"192 × 152 × 100 cm"},{"label":"Βάρος","value":"320 kg"}],"images":[{"src":"assets/photos/pianos/new/grotrian-steinweg-cabinet-192.jpg","width":314,"height":343,"alt":"Grotrian Steinweg Cabinet 192, πιάνο με ουρά, σε ουδέτερο φόντο","sourceSize":[400,350],"large":{"src":"assets/photos/pianos/new/grotrian-steinweg-cabinet-192-large.jpg","width":1400,"height":1516,"alt":"Grotrian Steinweg Cabinet 192, πιάνο με ουρά σε μαύρο γυαλιστερό φινίρισμα","fit":"contain","sourceSize":[1633,1603]}}],"pdf":{"src":"assets/docs/pianos/new/grotrian-steinweg-cabinet-192.pdf","label":"Φυλλάδιο κατασκευαστή","language":"Γερμανικά, αγγλικά, γαλλικά","bytes":528134},"order":7,"name":"Grotrian Steinweg Cabinet 192","summary":["Κάθε Cabinet έχει το μυστικό του. Με τα χρόνια διαμορφώνει τον αλάνθαστο χαρακτήρα και την αυθεντική του προσωπικότητα — και πάντα παραμένει Grotrian."],"body":["Ο κατασκευαστής το περιγράφει ως όργανο χωρίς συμβιβασμούς, τόσο στην εμφάνιση όσο και στον ήχο. Με μήκος 192 cm, το Cabinet είναι ένα γνήσιο όργανο μουσικής δωματίου με λεπτές αποχρώσεις στον ήχο, κατάλληλο για τη διδασκαλία σε ανώτερες μουσικές σχολές και για τον απαιτητικό μουσικό στο σπίτι."],"gallery":[{"src":"assets/photos/pianos/new/grotrian-steinweg-cabinet-192-detail.jpg","width":1600,"height":1081,"alt":"Κοντινό στο εσωτερικό του πιάνου, από το φυλλάδιο του Cabinet","fit":"cover","role":"gallery","sourceSize":[2603,1758]}],"availability":"order","availabilityLabel":"Κατόπιν παραγγελίας"},{"id":"new-10","slug":"grotrian-steinweg-charis-208","url":"/pianos/new/grotrian-steinweg-charis-208/","detailPage":"piano.html?model=grotrian-steinweg-charis-208","manufacturer":"Grotrian Steinweg","manufacturerSlug":"grotrian-steinweg","model":"Charis 208","type":"grand","typeLabel":"Πιάνο με ουρά","category":"Κλασικό πιάνο","sizeCm":208,"description":["Ο ήχος του είναι τόσο εντυπωσιακά δυναμικός και με τέτοια ισορροπημένη διαύγεια που αποτελεί μι απηγή έμπνευσης για τον πιανίστα."],"additional":["Κλασικό πιάνο"],"facts":[],"drawing":[],"finishes":[],"specModel":null,"specs":[{"label":"Τύπος","value":"Πιάνο με ουρά"},{"label":"Διαστάσεις","value":"208 × 153 × 100 cm"},{"label":"Βάρος","value":"350 kg"}],"images":[{"src":"assets/photos/pianos/new/grotrian-steinweg-charis-208.jpg","width":324,"height":345,"alt":"Grotrian Steinweg Charis 208, πιάνο με ουρά, σε ουδέτερο φόντο","sourceSize":[400,350],"large":{"src":"assets/photos/pianos/new/grotrian-steinweg-charis-208-large.jpg","width":1400,"height":1458,"alt":"Grotrian Steinweg Charis 208, πιάνο με ουρά σε μαύρο γυαλιστερό φινίρισμα","fit":"contain","sourceSize":[1732,1712]}}],"pdf":{"src":"assets/docs/pianos/new/grotrian-steinweg-charis-208.pdf","label":"Φυλλάδιο κατασκευαστή","language":"Γερμανικά, αγγλικά, γαλλικά","bytes":440254},"order":8,"name":"Grotrian Steinweg Charis 208","summary":["Ο ήχος του είναι τόσο εντυπωσιακά δυναμικός και τόσο ισορροπημένα διαυγής, που γίνεται πηγή έμπνευσης για τον πιανίστα."],"body":["Η Χάρις ήταν στην αρχαία Ελλάδα η θεότητα της χάρης και μούσα των καλών τεχνών· δεν είναι τυχαίο ότι το πιάνο με ουρά των 208 cm της Grotrian φέρει το όνομά της.","Σύμφωνα με τον κατασκευαστή, η ποιότητά του είναι καρπός της μακρόχρονης εμπειρίας της μονάδας του στο Braunschweig στην κατασκευή όρθιων πιάνων και πιάνων με ουρά."],"gallery":[{"src":"assets/photos/pianos/new/grotrian-steinweg-charis-208-detail.jpg","width":1600,"height":1081,"alt":"Κοντινό στο εσωτερικό του πιάνου, από το φυλλάδιο του Charis","fit":"cover","role":"gallery","sourceSize":[2603,1759]}],"availability":"order","availabilityLabel":"Κατόπιν παραγγελίας"},{"id":"new-11","slug":"grotrian-steinweg-concert-225","url":"/pianos/new/grotrian-steinweg-concert-225/","detailPage":"piano.html?model=grotrian-steinweg-concert-225","manufacturer":"Grotrian Steinweg","manufacturerSlug":"grotrian-steinweg","model":"Concert 225","type":"grand","typeLabel":"Πιάνο με ουρά","category":"Κλασικό πιάνο","sizeCm":225,"description":["Ο ήχος του είναι πιο πλούσιος από οποιονδήποτε άλλον.","Είναι σαν όλα τα άλλα πιάνα να μιλούσαν μια γλώσσα μεταξύ τους αλλά το Grotrian να μιλούσε μια άγνωστη γλώσσα με εξωτική προφορά. Θα μεθύσετε και θα γοητευτείτε από τον ήχο του. Όλη η δύναμη συγκεντρώνεται σε αυτό το συναυλιακό Grotrian πιάνο μήκους 225."],"additional":["Κλασικό πιάνο"],"facts":[],"drawing":[],"finishes":[],"specModel":null,"specs":[{"label":"Τύπος","value":"Πιάνο με ουρά"},{"label":"Μήκος","value":"225 cm"}],"images":[{"src":"assets/photos/pianos/new/grotrian-steinweg-concert-225.jpg","width":718,"height":730,"alt":"Grotrian Steinweg Concert 225, πιάνο με ουρά, σε ουδέτερο φόντο","sourceSize":[770,770]}],"pdf":null,"order":9,"name":"Grotrian Steinweg Concert 225","summary":["Ένα συναυλιακό πιάνο με ουρά μήκους 225 cm, με εξαιρετικά πλούσιο ήχο.","Είναι σαν όλα τα άλλα πιάνα να μιλούν μεταξύ τους μια κοινή γλώσσα και το Grotrian μια άγνωστη, με εξωτική προφορά. Στο Concert 225 συγκεντρώνεται όλη η δύναμη ενός συναυλιακού οργάνου."],"availability":"order","availabilityLabel":"Κατόπιν παραγγελίας"},{"id":"new-12","slug":"grotrian-steinweg-concert-royal-277","url":"/pianos/new/grotrian-steinweg-concert-royal-277/","detailPage":"piano.html?model=grotrian-steinweg-concert-royal-277","manufacturer":"Grotrian Steinweg","manufacturerSlug":"grotrian-steinweg","model":"Concert Royal 277","type":"grand","typeLabel":"Πιάνο με ουρά","category":"Κλασικό πιάνο","sizeCm":277,"description":["Το Concert Royal είναι αληθινά ένα μεγάλο πιάνο συναυλιών.","Η πληρότητα και η λαμπρότητα του ήχου, το κάνουν ένα όργανο για βιρτουόζους. Ένα πιάνο με ουρά για αξέχαστα βράδια μουσικής ευχαρίστησης."],"additional":["Κλασικό πιάνο"],"facts":[],"drawing":[],"finishes":[],"specModel":null,"specs":[{"label":"Τύπος","value":"Πιάνο με ουρά"},{"label":"Διαστάσεις","value":"277 × 156 × 100 cm"},{"label":"Βάρος","value":"550 kg"}],"images":[{"src":"assets/photos/pianos/new/grotrian-steinweg-concert-royal-277.jpg","width":378,"height":335,"alt":"Grotrian Steinweg Concert Royal 277, πιάνο με ουρά, σε ουδέτερο φόντο","sourceSize":[400,350],"large":{"src":"assets/photos/pianos/new/grotrian-steinweg-concert-royal-277-large.jpg","width":1400,"height":1241,"alt":"Grotrian Steinweg Concert Royal 277, πιάνο με ουρά σε μαύρο γυαλιστερό φινίρισμα","fit":"contain","sourceSize":[1603,1566]}}],"pdf":{"src":"assets/docs/pianos/new/grotrian-steinweg-concert-royal-277.pdf","label":"Φυλλάδιο κατασκευαστή","language":"Γερμανικά, αγγλικά, γαλλικά","bytes":561324},"order":10,"name":"Grotrian Steinweg Concert Royal 277","summary":["Το Concert Royal είναι ένα αληθινό μεγάλο πιάνο συναυλιών. Η πληρότητα και η λαμπρότητα του ήχου του το κάνουν όργανο για βιρτουόζους — ένα πιάνο με ουρά για αξέχαστες μουσικές βραδιές."],"body":["Ο κατασκευαστής παρομοιάζει τον ήχο του με εκείνον μιας ολόκληρης ορχήστρας. Ο τόνος, ο μηχανισμός και η κατασκευή του ανταποκρίνονται στις υψηλότερες απαιτήσεις ποιότητας, και η παρουσία του ακούγεται ως την τελευταία σειρά μεγάλων αιθουσών συναυλιών."],"gallery":[{"src":"assets/photos/pianos/new/grotrian-steinweg-concert-royal-277-detail.jpg","width":1600,"height":1081,"alt":"Κοντινό στο εσωτερικό του πιάνου, από το φυλλάδιο του Concert Royal","fit":"cover","role":"gallery","sourceSize":[2603,1758]}],"availability":"order","availabilityLabel":"Κατόπιν παραγγελίας"},{"id":"new-05","slug":"grotrian-steinweg-friedrich-grotrian","url":"/pianos/new/grotrian-steinweg-friedrich-grotrian/","detailPage":"piano.html?model=grotrian-steinweg-friedrich-grotrian","manufacturer":"Grotrian Steinweg","manufacturerSlug":"grotrian-steinweg","model":"Friedrich Grotrian","type":null,"typeLabel":null,"category":"Κλασικό πιάνο","sizeCm":null,"description":["Τα πιάνα Friedrich Grotrian στηρίζονται στη μεγάλη παράδοση της εταιρίας.","Όταν ακούτε ένα Friedrich Grotrian, αναγνωρίζετε αμέσως την πηγή της έμπνευσής του - τα όργανα από την παράδοση GROTRIAN. Εντούτοις, τα πιάνα Friedrich Grotrian διαφέρουν σε διάφορες λεπτομέρειες που τους επιτρέπει να προσφέρουν τέτοια εξαιρετικά καλή αξία για τα χρήματα που κοστίζει."],"additional":["Κλασικό πιάνο"],"facts":[],"drawing":[],"finishes":[],"specModel":null,"specs":[],"images":[{"src":"assets/photos/pianos/new/grotrian-steinweg-friedrich-grotrian.jpg","width":338,"height":323,"alt":"Grotrian Steinweg Friedrich Grotrian, σε ουδέτερο φόντο","sourceSize":[400,350]}],"pdf":null,"order":11,"name":"Grotrian Steinweg Friedrich Grotrian","summary":["Τα πιάνα Friedrich Grotrian στηρίζονται στη μεγάλη παράδοση της εταιρείας.","Ακούγοντας ένα Friedrich Grotrian, αναγνωρίζει κανείς αμέσως την πηγή της έμπνευσής του: τα όργανα της παράδοσης Grotrian. Διαφέρουν ωστόσο σε ορισμένες λεπτομέρειες, κάτι που τους επιτρέπει να προσφέρουν εξαιρετική σχέση ποιότητας και τιμής."],"availability":"order","availabilityLabel":"Κατόπιν παραγγελίας"},{"id":"new-18","slug":"petrof-p-118-p1","url":"/pianos/new/petrof-p-118-p1/","detailPage":"piano.html?model=petrof-p-118-p1","manufacturer":"Petrof","manufacturerSlug":"petrof","model":"P 118 P1","type":"upright","typeLabel":"Όρθιο πιάνο","category":"Κλασικό πιάνο","sizeCm":118,"description":["Το όρθιο πιάνο P 118 P1 ανήκει στα πιάνα μεσαίου ύψους.","Χάρη στις διαστάσεις του, είναι ιδανικό για μικρούς εσωτερικούς χώρους και ιδιαίτερα για λόγους εκμάθησης και κατάρτισης. Είναι ένα αγαπημένο μοντέλο για ευρύτερη χρήση.Το σώμα του P1 όρθιου πιάνου ενώνει το κλασικό τελείωμα με σύγχρονα ενσωματωμένα στοιχεία."],"additional":["Κλασικό πιάνο"],"facts":[],"drawing":[{"label":"a","value":"542 mm ° 21,34“"},{"label":"b","value":"1175 mm ° 46,26“"},{"label":"height","value":"Width - 1446 mm ° 56,93“"},{"label":"weight","value":"Weight – 199 kg ° 438 lb"}],"finishes":["White, high polish 0001","Black, high polish 0801","Walnut, high polish 2251","Walnut, satin 2357","Mahogany, high polish 3281","Mahogany, satin 3287","Beech, satin 4107","Cherry, satin 6217","Alder, satin 8107"],"specModel":"P 118 P1","specs":[{"label":"Τύπος","value":"Όρθιο πιάνο"},{"label":"Μέγεθος","value":"117,5 × 144,6 × 54,2 cm"},{"label":"Τελείωμα","value":"Λευκό γυαλιστερό, μαύρο γυαλιστερό, καρυδιά γυαλιστερό, καρυδιά σατινέ, μαόνι γυαλιστερό, μαόνι σατινέ, οξιά σατινέ, κερασιά σατινέ, σκλήθρο σατινέ"}],"images":[{"src":"assets/photos/pianos/new/petrof-p-118-p1.jpg","width":400,"height":395,"alt":"Petrof P 118 P1, όρθιο πιάνο, σε ουδέτερο φόντο","sourceSize":[400,395]}],"pdf":null,"order":12,"name":"Petrof P 118 P1","summary":["Το P 118 P1 είναι όρθιο πιάνο μεσαίου ύψους.","Χάρη στις διαστάσεις του είναι ιδανικό για μικρούς χώρους και ιδιαίτερα για εκμάθηση και μελέτη — ένα αγαπημένο μοντέλο για ευρεία χρήση. Το κέλυφος του P1 συνδυάζει το κλασικό φινίρισμα με σύγχρονα στοιχεία."],"availability":"stock","availabilityLabel":"Στην έκθεση"},{"id":"new-19","slug":"petrof-p-125","url":"/pianos/new/petrof-p-125/","detailPage":"piano.html?model=petrof-p-125","manufacturer":"Petrof","manufacturerSlug":"petrof","model":"P 125","type":"upright","typeLabel":"Όρθιο πιάνο","category":"Κλασικό πιάνο","sizeCm":125,"description":["Το P 125 είναι ένα όρθιο πιάνο από την υψηλότερη σειρά οργάνων. Είναι μια ευρείας χρήσεως αγαπημένη λύση.","Είναι κατάλληλο για το σπίτι και τη σχολική διδασκαλία, για τις ανάγκες της μελέτης των επαγγελματικών φορέων, αλλά και για τα μουσικά σύνολα. Ο ήχος του επίσης θα ικανοποιήσει ακροατήρια λεσχών. Το τελείωμα του, συνδυάζει το κλασσικό και σύγχρονο ύφος που συμπληρώνεται με διακοσμητικά στοιχεία."],"additional":["Κλασικό πιάνο"],"facts":[],"drawing":[{"label":"a","value":"585 mm ° 23,03“"},{"label":"b","value":"1250 mm ° 49,21“"},{"label":"height","value":"Width - 1463 mm ° 57,60“"},{"label":"weight","value":"Weight – 209 kg ° 460 lb"}],"finishes":["White, high polish 0001","Ivory white, high polish 0051","Black, high polish 0801","Walnut, high polish 2251","Mahogany, high polish 3281"],"specModel":"P 125 G1","specs":[{"label":"Τύπος","value":"Όρθιο πιάνο"},{"label":"Μέγεθος","value":"125 × 146,3 × 58,5 cm"},{"label":"Τελείωμα","value":"Λευκό γυαλιστερό, ιβουάρ γυαλιστερό, μαύρο γυαλιστερό, καρυδιά γυαλιστερό, μαόνι γυαλιστερό"}],"images":[{"src":"assets/photos/pianos/new/petrof-p-125.jpg","width":400,"height":396,"alt":"Petrof P 125, όρθιο πιάνο, σε ουδέτερο φόντο","sourceSize":[400,396]}],"pdf":null,"order":13,"name":"Petrof P 125","summary":["Το P 125 είναι όρθιο πιάνο από την υψηλότερη σειρά οργάνων της Petrof και μια αγαπημένη λύση για ευρεία χρήση.","Είναι κατάλληλο για το σπίτι και τη διδασκαλία, για τη μελέτη επαγγελματιών και για μουσικά σύνολα, ενώ ο ήχος του ικανοποιεί και το ακροατήριο μουσικών χώρων. Το κέλυφός του συνδυάζει κλασικό και σύγχρονο ύφος, με διακοσμητικά στοιχεία."],"availability":"stock","availabilityLabel":"Στην έκθεση"},{"id":"new-20","slug":"petrof-p-131-e1","url":"/pianos/new/petrof-p-131-e1/","detailPage":"piano.html?model=petrof-p-131-e1","manufacturer":"Petrof","manufacturerSlug":"petrof","model":"P 131 E1","type":"upright","typeLabel":"Όρθιο πιάνο","category":"Κλασικό πιάνο","sizeCm":131,"description":["Το P 131 E1 όρθιο πιάνο ταξινομείται πολύ ψηλά σε θέση μεταξύ άλλων ομοίων του.","Αυτά είναι πιάνα με πολύ μεγάλη ακουστική δυνατότητα. Ταιριάζουν όχι μόνο στο εσωτερικό διαμερισμάτων και τα σχολεία μουσικής, αλλά και τις εκθέσεις πιάνων παρουσίασης μέσα σε μια ορχήστρα ή στις διαφορετικές δημόσιες σκηνές.","Το E1 μοντέλο έχει μια μη παραδοσιακή θέση αναλόγιου, η οποία επιτρέπει στις νότες να τοποθετηθούν μέσα σε μια ευρύτερη περιοχή και στο ύψος του ματιού του πιανίστα."],"additional":["Κλασικό πιάνο"],"facts":[],"drawing":[{"label":"a","value":"602 mm ° 23,70“"},{"label":"b","value":"1316 mm ° 51,81“"},{"label":"height","value":"Width - 1454 mm ° 57,24“"},{"label":"weight","value":"Weight – 230 kg ° 506 lb"}],"finishes":["Black, high polish 0801","Walnut, high polish 2251","Mahogany, high polish 3281"],"specModel":"P 131 M1","specs":[{"label":"Τύπος","value":"Όρθιο πιάνο"},{"label":"Πλάτος","value":"1454 mm"},{"label":"Βάθος","value":"602 mm"},{"label":"Ύψος","value":"1316 mm"},{"label":"Βάρος","value":"230 kg"},{"label":"Φινιρίσματα κατασκευαστή","value":"Μαύρο γυαλιστερό (0801), Καρυδιά γυαλιστερό (2251), Μαόνι γυαλιστερό (3281)"}],"images":[{"src":"assets/photos/pianos/new/petrof-p-131-e1.jpg","width":382,"height":389,"alt":"Petrof P 131 E1, όρθιο πιάνο, σε ουδέτερο φόντο","sourceSize":[400,409]}],"pdf":null,"order":14,"name":"Petrof P 131 E1","summary":["Το όρθιο πιάνο P 131 E1 κατατάσσεται πολύ ψηλά ανάμεσα στα όργανα της κατηγορίας του."],"body":["Πρόκειται για πιάνα με πολύ μεγάλες ακουστικές δυνατότητες, κατάλληλα όχι μόνο για κατοικίες και μουσικές σχολές, αλλά και για παρουσιάσεις με ορχήστρα ή για διάφορες δημόσιες σκηνές.","Το μοντέλο E1 έχει μη παραδοσιακή θέση αναλογίου, που επιτρέπει να τοποθετηθούν οι παρτιτούρες σε ευρύτερη επιφάνεια και στο ύψος του ματιού του πιανίστα."],"availability":"stock","availabilityLabel":"Στην έκθεση"},{"id":"new-21","slug":"petrof-p-135-k1","url":"/pianos/new/petrof-p-135-k1/","detailPage":"piano.html?model=petrof-p-135-k1","manufacturer":"Petrof","manufacturerSlug":"petrof","model":"P 135 K1","type":"upright","typeLabel":"Όρθιο πιάνο","category":"Κλασικό πιάνο","sizeCm":135,"description":["Το P 135 K1 όρθιο πιάνο ταξινομείται στην υψηλότερη θέση όρθιων πιάνων.","Αυτά είναι πιάνα με τη μέγιστη ακουστική δυνατότητα που είναι επομένως τα αγαπημένα των επαγγελματιών πιανίστων με απαιτήσεις. Ταιριάζουν όχι μόνο στο εσωτερικό διαμερισμάτων και τα σχολεία μουσικής, αλλά και τις εκΤο P 135 K1 όρθιο πιάνο ταξινομείται στην υψηλότερη θέση όρθιων πιάνων. Αυτά είναι πιάνα με τη μέγιστη ακουστική δυνατότητα που είναι επομένως τα αγαπημένα των επαγκελματιών πιανίστων με απιτήσεις. Ταιριάζουν όχι μόνο στο εσωτερικό διαμερισμάτων και τα σχολεία μουσικής, αλλά και τις εκθέσεις πιάνων παρουσίασης μέσα σε μια ορχήστρα ή στις διαφορετικές δημόσιες σκηνές.","Το P 131 E1 όρθιο πιάνο ταξινομείται στην υψηλότερη θέση όρθιων πιάνων. Αυτά είναι πιάνα με τη μέγιστη ακουστική δυνατότητα που είναι επομένως τα αγαπημένα των επαγκελματιών πιανίστων με απιτήσεις. Ταιριάζουν όχι μόνο στο εσωτερικό διαμερισμάτων και τα σχολεία μουσικής, αλλά και τις εκθέσεις πιάνων παρουσίασης μέσα σε μια ορχήστρα ή στις διαφορετικές δημόσιες σκηνές. θέσεις πιάνων παρουσίασης μέσα σε μια ορχήστρα ή στις διαφορετικές δημόσιες σκηνές. Το όργανο προσφέρει πλήθος δυνατοτήτων για τον έλεγχο του ήχου από τον πιανίστα.Αυτό επιτυγχάνεται από τα 3 πεντάλ ποδιών και ένα χειροκίνητο μοχλό."],"additional":["Κλασικό πιάνο"],"facts":[],"drawing":[{"label":"a","value":"606 mm ° 23,86“"},{"label":"b","value":"1341 mm ° 52,80“"},{"label":"height","value":"Width - 1446 mm ° 56,93“"},{"label":"weight","value":"Weight – 243 kg ° 535 lb"}],"finishes":["Black, high polish 0801"],"specModel":"P 135 K1","specs":[{"label":"Τύπος","value":"Όρθιο πιάνο"},{"label":"Μέγεθος","value":"135,1 × 144,6 × 61 cm"},{"label":"Τελείωμα","value":"Μαύρο γυαλιστερό"}],"images":[{"src":"assets/photos/pianos/new/petrof-p-135-k1.jpg","width":685,"height":682,"alt":"Petrof P 135 K1, όρθιο πιάνο, σε ουδέτερο φόντο","sourceSize":[770,734]}],"pdf":null,"order":15,"name":"Petrof P 135 K1","summary":["Το όρθιο πιάνο P 135 K1 κατατάσσεται στην κορυφή των όρθιων πιάνων."],"body":["Είναι πιάνα με τις μέγιστες ακουστικές δυνατότητες, γι’ αυτό και αγαπημένα των απαιτητικών επαγγελματιών πιανιστών. Ταιριάζουν όχι μόνο σε κατοικίες και μουσικές σχολές, αλλά και σε παρουσιάσεις με ορχήστρα ή σε διάφορες δημόσιες σκηνές.","Το όργανο δίνει στον πιανίστα πολλές δυνατότητες ελέγχου του ήχου, μέσω τριών πεντάλ και ενός χειροκίνητου μοχλού."],"availability":"order","availabilityLabel":"Κατόπιν παραγγελίας"},{"id":"new-22","slug":"petrof-p-iv-grand","url":"/pianos/new/petrof-p-iv-grand/","detailPage":"piano.html?model=petrof-p-iv-grand","manufacturer":"Petrof","manufacturerSlug":"petrof","model":"P IV Grand","type":"grand","typeLabel":"Πιάνο με ουρά","category":"Κλασικό πιάνο","sizeCm":172,"description":["Το P IV είναι ένα πιάνο με ούρα προορισμένο και για μελέτη στο σπίτι και για εκπαιδευτικούς λόγους.","Μπορεί να γίνει ένα όμορφο κομμάτι του σπιτιού και ο τόνος του θα ευχαριστήσει όλους τους πιανίστες."],"additional":["Κλασικό πιάνο","Μέγεθος: 172 cm","ΣΤΥΛ: Standard Grand Series","ΤΕΛΕΙΩΜΑ: Μαόνι γυαλιστερό"],"facts":[{"label":"Μέγεθος","value":"172 cm"},{"label":"Στυλ","value":"Standard Grand Series"},{"label":"Τελείωμα","value":"Μαόνι γυαλιστερό"}],"drawing":[],"finishes":[],"specModel":null,"specs":[{"label":"Τύπος","value":"Πιάνο με ουρά"},{"label":"Μέγεθος","value":"172 cm"},{"label":"Στυλ","value":"Standard Grand Series"},{"label":"Τελείωμα","value":"Μαόνι γυαλιστερό"}],"images":[{"src":"assets/photos/pianos/new/petrof-p-iv-grand.jpg","width":400,"height":509,"alt":"Petrof P IV Grand, πιάνο με ουρά, σε ουδέτερο φόντο","sourceSize":[400,509]}],"pdf":null,"order":16,"name":"Petrof P IV Grand","summary":["Το P IV είναι πιάνο με ουρά για μελέτη στο σπίτι και για εκπαιδευτική χρήση.","Μπορεί να γίνει ένα όμορφο κομμάτι του σπιτιού, με έναν τόνο που θα ευχαριστήσει κάθε πιανίστα."],"availability":"order","availabilityLabel":"Κατόπιν παραγγελίας"},{"id":"new-23","slug":"petrof-p-210-pasat-grand","url":"/pianos/new/petrof-p-210-pasat-grand/","detailPage":"piano.html?model=petrof-p-210-pasat-grand","manufacturer":"Petrof","manufacturerSlug":"petrof","model":"P 210 Pasat Grand","type":"grand","typeLabel":"Πιάνο με ουρά","category":"Κλασικό πιάνο","sizeCm":210,"description":["Το P 210 Pasat πιάνο με ουρά είναι μια καινοτομία στη master σειρά πιάνων.","Ο ρομαντικός, διαυγής και μελωδικός τόνος τον ταξινομεί μεταξύ των καλύτερων πιάνων στις διεθνείς εκθέσεις πιάνων.Οι ακουστικοί παράμετροι του είναι σε θέση να ενισχύσουν έξοχα το συναίσθημα που προέρχεται απ'ο τη μουσική. Οι διαστάσεις του το καθιστούν ιδανικό για αίθουσες συναυλιών,στούντιο αλλά και σπίτια."],"additional":["Κλασικό πιάνο"],"facts":[],"drawing":[{"label":"a","value":"1525 mm ° 60,04\""},{"label":"b","value":"2100 mm ° 82,68\""},{"label":"height","value":"Height - 1006 mm ° 39,60\""},{"label":"weight","value":"Weight – 410 kg °902 lb"}],"finishes":["Black, high polish 0801"],"specModel":"P 210 Pasat","specs":[{"label":"Τύπος","value":"Πιάνο με ουρά"},{"label":"Μέγεθος","value":"210 × 152,5 × 102,5 cm"},{"label":"Τελείωμα","value":"Μαύρο γυαλιστερό"}],"images":[{"src":"assets/photos/pianos/new/petrof-p-210-pasat-grand.jpg","width":400,"height":411,"alt":"Petrof P 210 Pasat Grand, πιάνο με ουρά, σε ουδέτερο φόντο","sourceSize":[400,600]}],"pdf":null,"order":17,"name":"Petrof P 210 Pasat Grand","summary":["Το πιάνο με ουρά P 210 Pasat είναι μια καινοτομία στη σειρά Master της Petrof."],"body":["Ο ρομαντικός, διαυγής και μελωδικός τόνος του το κατατάσσει ανάμεσα στα καλύτερα πιάνα των διεθνών εκθέσεων. Οι ακουστικές του παράμετροι ενισχύουν έξοχα το συναίσθημα της μουσικής, ενώ οι διαστάσεις του το κάνουν ιδανικό για αίθουσες συναυλιών, στούντιο αλλά και σπίτια."],"availability":"order","availabilityLabel":"Κατόπιν παραγγελίας"},{"id":"new-24","slug":"petrof-p-284-mistral-grand","url":"/pianos/new/petrof-p-284-mistral-grand/","detailPage":"piano.html?model=petrof-p-284-mistral-grand","manufacturer":"Petrof","manufacturerSlug":"petrof","model":"P 284 Mistral Grand","type":"grand","typeLabel":"Πιάνο με ουρά","category":"Κλασικό πιάνο","sizeCm":284,"description":["Το P 284 Mistral πιάνο είναι ένα βελτιωμένο μοντέλο της σειράς Master φτιαγμένο αυστηρά για επαγγελματίες πιανίστες και επαγγελματικούς χώρους συναυλιών.","Χάρη στις ακουστικές του δυνατότητες δίνει στον πιανίστα την ευκαιρία να ερμηνεύσει και τα πιο δύσκολα,μουσικά, κομμάτια. Έχει τον χαρακτηριστικό ήχο και την εξαιρετικά όμορφη εμφάνιση των πιάνων Petrof."],"additional":["Κλασικό πιάνο"],"facts":[],"drawing":[{"label":"a","value":"1580 mm ° 62,20“"},{"label":"b","value":"2840 mm ° 111,42“"},{"label":"height","value":"Height - 1014 mm ° 39,92“"},{"label":"weight","value":"Weight – 560 kg °1232 lb"}],"finishes":["Black, high polish 0801"],"specModel":"P 284 Mistral","specs":[{"label":"Τύπος","value":"Πιάνο με ουρά"},{"label":"Μέγεθος","value":"284 × 158 × 103 cm"},{"label":"Τελείωμα","value":"Μαύρο γυαλιστερό"}],"images":[{"src":"assets/photos/pianos/new/petrof-p-284-mistral-grand.jpg","width":363,"height":308,"alt":"Petrof P 284 Mistral Grand, πιάνο με ουρά, σε ουδέτερο φόντο","sourceSize":[400,308]}],"pdf":null,"order":18,"name":"Petrof P 284 Mistral Grand","summary":["Το πιάνο με ουρά P 284 Mistral είναι εξελιγμένο μοντέλο της σειράς Master, φτιαγμένο για επαγγελματίες πιανίστες και επαγγελματικούς χώρους συναυλιών.","Χάρη στις ακουστικές του δυνατότητες, επιτρέπει στον πιανίστα να ερμηνεύσει και τα πιο απαιτητικά έργα. Έχει τον χαρακτηριστικό ήχο και την ιδιαίτερα όμορφη εμφάνιση των πιάνων Petrof."],"availability":"order","availabilityLabel":"Κατόπιν παραγγελίας"},{"id":"new-13","slug":"ronisch-model-115","url":"/pianos/new/ronisch-model-115/","detailPage":"piano.html?model=ronisch-model-115","manufacturer":"Rönisch","manufacturerSlug":"ronisch","model":"Model 115","type":"upright","typeLabel":"Όρθιο πιάνο","category":"Κλασικό πιάνο","sizeCm":115,"description":["Μεσαίο μέγεθος-Αξιοπρόσεχτος ήχος. Συμβατό και για χρήση σε μικρότερους χώρους ενσωματώνοντας την πιο πρόσφατη τεχνολογία σχεδιασμού της ποιότητας Rönisch.","Το μοντέλο 115 παράγει εκπληκτικό βάθος για το μέγεθος του ηχείου του. Η απλή κομψότητα και ο καλλιεργημένος τόνος αυτού του χαμηλότερου όρθιου παρέχουν μια εισαγωγή στη διακεκριμένη οικογένεια Rönisch των άριστων πιάνων."],"additional":["Κλασικό πιάνο"],"facts":[],"drawing":[],"finishes":[],"specModel":null,"specs":[],"images":[{"src":"assets/photos/pianos/new/ronisch-model-115.jpg","width":352,"height":296,"alt":"Rönisch Model 115, όρθιο πιάνο, σε ουδέτερο φόντο","sourceSize":[400,386]}],"pdf":null,"order":19,"name":"Rönisch Model 115","summary":["Μεσαίο μέγεθος, αξιοπρόσεκτος ήχος. Κατάλληλο και για μικρότερους χώρους, ενσωματώνει την πιο πρόσφατη σχεδιαστική τεχνολογία της Rönisch.","Το Model 115 προσφέρει εντυπωσιακό βάθος για το μέγεθος του ηχείου του. Η απλή κομψότητα και ο καλλιεργημένος τόνος του αποτελούν την εισαγωγή στη διακεκριμένη οικογένεια πιάνων της Rönisch."],"availability":"order","availabilityLabel":"Κατόπιν παραγγελίας"},{"id":"new-14","slug":"ronisch-model-118","url":"/pianos/new/ronisch-model-118/","detailPage":"piano.html?model=ronisch-model-118","manufacturer":"Rönisch","manufacturerSlug":"ronisch","model":"Model 118","type":"upright","typeLabel":"Όρθιο πιάνο","category":"Κλασικό πιάνο","sizeCm":118,"description":["Προσφέρει τον ίδιο άριστο τόνο και την ίδια αίσθηση αφής με το μοντέλο 115 αλλά και την απλή κομψότητα της καμπίνας ενός υψηλότερου πιάνου","Το μοντέλο 118 διατείθεται σε μια ευρύτερη ποικιλία διαφορετικών στυλ και επίλεκτων ξύλων, σπάνιων καπλαμάδων και ασυνήθιστων χρωμάτων. Το Rönisch συνεχίζει τη μακροχρόνια ιστορική συμβολή του στην πλούσια δημιουργική παράδοση διακόσμησης και αισθητικής."],"additional":["Κλασικό πιάνο"],"facts":[],"drawing":[],"finishes":[],"specModel":null,"specs":[],"images":[{"src":"assets/photos/pianos/new/ronisch-model-118.jpg","width":400,"height":400,"alt":"Rönisch Model 118, όρθιο πιάνο, σε ουδέτερο φόντο","sourceSize":[400,400]}],"pdf":null,"order":20,"name":"Rönisch Model 118","summary":["Προσφέρει τον ίδιο εξαιρετικό τόνο και την ίδια αίσθηση αφής με το Model 115, με την απλή κομψότητα ενός ψηλότερου πιάνου.","Το Model 118 διατίθεται σε μεγαλύτερη ποικιλία στυλ και επιλεγμένων ξύλων, σπάνιων καπλαμάδων και ασυνήθιστων χρωμάτων, συνεχίζοντας τη μακρά παράδοση της Rönisch στη διακόσμηση και την αισθητική."],"availability":"stock","availabilityLabel":"Στην έκθεση"},{"id":"new-16","slug":"ronisch-model-132","url":"/pianos/new/ronisch-model-132/","detailPage":"piano.html?model=ronisch-model-132","manufacturer":"Rönisch","manufacturerSlug":"ronisch","model":"Model 132","type":"upright","typeLabel":"Όρθιο πιάνο","category":"Κλασικό πιάνο","sizeCm":132,"description":["Πίσω πλαίσιο που θυμίζει φρούριο, μεγάλου μήκους χορδές, επεκτατικό ηχείο, μεγάλα πλήκτρα που ενεργούν με αστραπιαία ταχύτητα.","Όλα τα πλεονεκτήματα ενός άψογου πιάνου με ουρά είναι εμφανής στη θαυμάσια εφαρμοσμένη μηχανική του πιο ψηλού όρθιου πιάνου της Rönisch. Η ογκώγης δύναμη του μπάσου και οι κρυστάλινες ψηλές νότες επιτυγχάνουν την μέγιστη μουσική ποικιλία και απόχρωση. Οι σύνθετες ορχηστρικές αρμονικές συνδυάζονται σε μια άπειρη παλέτα τονικού χρώματος έχουν σαν αποτέλεσμα τον ήχο Rönisch, για εκείνους που επιθυμούν τον καλύτερο δυνατό από όρθιο."],"additional":["Κλασικό πιάνο"],"facts":[],"drawing":[],"finishes":[],"specModel":null,"specs":[],"images":[{"src":"assets/photos/pianos/new/ronisch-model-132.jpg","width":269,"height":373,"alt":"Rönisch Model 132, όρθιο πιάνο, σε ουδέτερο φόντο","sourceSize":[400,386]}],"pdf":null,"order":21,"name":"Rönisch Model 132","summary":["Πίσω σκελετός που θυμίζει φρούριο, μακριές χορδές, ευρύ ηχείο και μεγάλα πλήκτρα με αστραπιαία ανταπόκριση."],"body":["Στον μηχανισμό του ψηλότερου όρθιου πιάνου της Rönisch είναι εμφανή όλα τα πλεονεκτήματα ενός άψογου πιάνου με ουρά.","Η ογκώδης δύναμη του μπάσου και οι κρυστάλλινες ψηλές νότες δίνουν τη μέγιστη μουσική ποικιλία και απόχρωση· οι πλούσιες αρμονικές συνθέτουν μια ατελείωτη παλέτα τονικών χρωμάτων. Αυτός είναι ο ήχος Rönisch, για όσους ζητούν τον καλύτερο δυνατό ήχο από ένα όρθιο πιάνο."],"availability":"stock","availabilityLabel":"Στην έκθεση"},{"id":"new-15","slug":"ronisch-model-123","url":"/pianos/new/ronisch-model-123/","detailPage":"piano.html?model=ronisch-model-123","manufacturer":"Rönisch","manufacturerSlug":"ronisch","model":"Model 123","type":null,"typeLabel":null,"category":"Κλασικό πιάνο","sizeCm":123,"description":["Για τον επαγγελματία πιανίστα, τα μακρύτερα μέρη της μηχανής συνδιάζονται με ένα διευρυμένο ηχείο και με μεγαλύτερου μήκους χορδές...","...προσφέρουν μεγαλύτερη ευαισθησία αφής και μεγαλύτερη δυναμική σε αυτό το μοντέλο Rönisch."],"additional":["Κλασικό πιάνο"],"facts":[],"drawing":[],"finishes":[],"specModel":null,"specs":[],"images":[{"src":"assets/photos/pianos/new/ronisch-model-123.jpg","width":677,"height":639,"alt":"Rönisch Model 123, σε ουδέτερο φόντο","sourceSize":[770,743]}],"pdf":null,"order":22,"name":"Rönisch Model 123","summary":["Για τον επαγγελματία πιανίστα: τα μακρύτερα μέρη του μηχανισμού, σε συνδυασμό με διευρυμένο ηχείο και μακρύτερες χορδές, χαρίζουν μεγαλύτερη ευαισθησία αφής και μεγαλύτερη δυναμική."],"availability":"stock","availabilityLabel":"Στην έκθεση"},{"id":"new-28","slug":"young-chang-y-121","url":"/pianos/new/young-chang-y-121/","detailPage":"piano.html?model=young-chang-y-121","manufacturer":"Young Chang","manufacturerSlug":"young-chang","model":"Y 121","type":"upright","typeLabel":"Όρθιο πιάνο","category":"Κλασικό πιάνο","sizeCm":121,"description":["Είτε η αναζήτηση μουσικής είναι ένα επάγγελμα, ένα πάθος, ή και τα δύο για σας, το Y-121 θα καλύψει τις απαιτήσεις σας για διάκριση.","Άμεση ανταπόκριση στο άγγιγμα σας. Δώστε ζωή στη μουσική με το Y-121, για το σπίτι ή το στούντιό σας."],"additional":["Κλασικό πιάνο","ΜΕΓΕΘΟΣ: 121 x 150 x 61","ΣΤΥΛ: Professional Upright","ΤΕΛΕΙΩΜΑ: Ebony Polish, Mahogany Red Polish, Walnut Polish,White Polish"],"facts":[{"label":"Μέγεθος","value":"121 x 150 x 61"},{"label":"Στυλ","value":"Professional Upright"},{"label":"Τελείωμα","value":"Ebony Polish, Mahogany Red Polish, Walnut Polish,White Polish"}],"drawing":[],"finishes":[],"specModel":null,"specs":[{"label":"Τύπος","value":"Όρθιο πιάνο"},{"label":"Μέγεθος","value":"121 × 150 × 61 cm"},{"label":"Στυλ","value":"Professional Upright"},{"label":"Τελείωμα","value":"Μαύρο γυαλιστερό, κόκκινο μαόνι γυαλιστερό, καρυδιά γυαλιστερό, λευκό γυαλιστερό (Ebony, Mahogany Red, Walnut, White Polish)"}],"images":[{"src":"assets/photos/pianos/new/young-chang-y-121.jpg","width":400,"height":362,"alt":"Young Chang Y 121, όρθιο πιάνο, σε ουδέτερο φόντο","sourceSize":[400,362]}],"pdf":null,"order":23,"name":"Young Chang Y 121","summary":["Είτε η μουσική είναι για εσάς επάγγελμα, πάθος ή και τα δύο, το Y 121 ανταποκρίνεται στις απαιτήσεις σας.","Ανταποκρίνεται άμεσα στο άγγιγμά σας και δίνει ζωή στη μουσική, στο σπίτι ή στο στούντιο."],"availability":"stock","availabilityLabel":"Στην έκθεση"},{"id":"new-27","slug":"young-chang-y-131","url":"/pianos/new/young-chang-y-131/","detailPage":"piano.html?model=young-chang-y-131","manufacturer":"Young Chang","manufacturerSlug":"young-chang","model":"Y 131","type":"upright","typeLabel":"Όρθιο πιάνο","category":"Κλασικό πιάνο","sizeCm":131,"description":["Το Y 131 ανήκει στην επαγγελματική σειρά πιάνων σχεδιασμένα για να ικανοποιήσουν τον πιο απαιτητικό μουσικό.","Ένα αληθινό έργο της τέχνης, αυτό το πιάνο έχει άμεση ανταπόκριση στο παίξιμο και έναν έξοχο τόνο. Διαυγής ήχος και εξαιρετική ομορφιά συνδυάζονται για να δημιουργήσουν ένα πιάνο τέλειο για τις ανάγκες οποιουδήποτε σπιτιού ή στούντιο."],"additional":["Κλασικό πιάνο","ΜΕΓΕΘΟΣ: 131 x 155 x 60","ΣΤΥΛ: Professional Upright","ΤΕΛΕΙΩΜΑ: Ebony Polish, Mahogany Red Polish, Walnut Polish"],"facts":[{"label":"Μέγεθος","value":"131 x 155 x 60"},{"label":"Στυλ","value":"Professional Upright"},{"label":"Τελείωμα","value":"Ebony Polish, Mahogany Red Polish, Walnut Polish"}],"drawing":[],"finishes":[],"specModel":null,"specs":[{"label":"Τύπος","value":"Όρθιο πιάνο"},{"label":"Μέγεθος","value":"131 × 155 × 60 cm"},{"label":"Στυλ","value":"Professional Upright"},{"label":"Τελείωμα","value":"Μαύρο γυαλιστερό, κόκκινο μαόνι γυαλιστερό, καρυδιά γυαλιστερό (Ebony, Mahogany Red, Walnut Polish)"}],"images":[{"src":"assets/photos/pianos/new/young-chang-y-131.jpg","width":400,"height":358,"alt":"Young Chang Y 131, όρθιο πιάνο, σε ουδέτερο φόντο","sourceSize":[400,358]}],"pdf":null,"order":24,"name":"Young Chang Y 131","summary":["Το Y 131 ανήκει στην επαγγελματική σειρά πιάνων της Young Chang, σχεδιασμένη για τον πιο απαιτητικό μουσικό.","Με άμεση ανταπόκριση στο παίξιμο και έξοχο τόνο, συνδυάζει διαυγή ήχο και ιδιαίτερη ομορφιά — ένα πιάνο για κάθε σπίτι ή στούντιο."],"availability":"stock","availabilityLabel":"Στην έκθεση"},{"id":"new-01","slug":"young-chang-y-150","url":"/pianos/new/young-chang-y-150/","detailPage":"piano.html?model=young-chang-y-150","manufacturer":"Young Chang","manufacturerSlug":"young-chang","model":"Y-150","type":"grand","typeLabel":"Πιάνο με ουρά","category":"Κλασικό πιάνο","sizeCm":150,"description":["Ενα υπέροχο πιάνο σε μια υπέροχη τιμή! Αποκτήστε ενα πιάνο με όλα τα χαρακτηριστικά γνωρίσματα των πιάνων με ουρά Young Chang, σε χαμηλή τιμή!"],"additional":["Κλασικό πιάνο","Μοντέλο Y-150","Μέγεθος: 150 x 148 x 101","Στυλ: Baby Grand","Τελείωμα: Ebony polish"],"facts":[{"label":"Μέγεθος","value":"150 x 148 x 101"},{"label":"Στυλ","value":"Baby Grand"},{"label":"Τελείωμα","value":"Ebony polish"}],"drawing":[],"finishes":[],"specModel":null,"specs":[{"label":"Τύπος","value":"Πιάνο με ουρά"},{"label":"Μέγεθος","value":"150 × 148 × 101 cm"},{"label":"Στυλ","value":"Baby Grand"},{"label":"Τελείωμα","value":"Μαύρο γυαλιστερό (Ebony polish)"}],"images":[{"src":"assets/photos/pianos/new/young-chang-y-150.jpg","width":290,"height":311,"alt":"Young Chang Y-150, πιάνο με ουρά, σε ουδέτερο φόντο","sourceSize":[400,350]}],"pdf":null,"order":25,"name":"Young Chang Y-150","summary":["Ένα πιάνο με ουρά τύπου baby grand, με όλα τα χαρακτηριστικά γνωρίσματα των πιάνων με ουρά της Young Chang."],"availability":"order","availabilityLabel":"Κατόπιν παραγγελίας"},{"id":"new-17","slug":"young-chang-y-152","url":"/pianos/new/young-chang-y-152/","detailPage":"piano.html?model=young-chang-y-152","manufacturer":"Young Chang","manufacturerSlug":"young-chang","model":"Y 152","type":"grand","typeLabel":"Πιάνο με ουρά","category":"Κλασικό πιάνο","sizeCm":152,"description":["Αναμείνετε την βέλτιστη χημεία μεταξύ οργάνου και πιανίστα από το Y 152 Grand πιάνο.","Σε αυτό το έργο τέχνης κομψά συνδιάζονται η τέχνη της χειροτεχνίας και η μεθυστική ομορφιά. Με την προσεκτική κατασκευασμένη μηχανή, τα χωριστά σταθμισμένα κλειδιά,το Y-152 απολαμβάνει την υψηλή ανταπόκριση των πλήκτρων στη μουσικη έμπνευση του καλλιτέχνη."],"additional":["Κλασικό πιάνο","Μέγεθος: 152 x 148 x 101","Στυλ: Classic Grand","Τελείωμα: Ebony Polish"],"facts":[{"label":"Μέγεθος","value":"152 x 148 x 101"},{"label":"Στυλ","value":"Classic Grand"},{"label":"Τελείωμα","value":"Ebony Polish"}],"drawing":[],"finishes":[],"specModel":null,"specs":[{"label":"Τύπος","value":"Πιάνο με ουρά"},{"label":"Μέγεθος","value":"152 × 148 × 101 cm"},{"label":"Στυλ","value":"Classic Grand"},{"label":"Τελείωμα","value":"Μαύρο γυαλιστερό (Ebony Polish)"}],"images":[{"src":"assets/photos/pianos/new/young-chang-y-152.jpg","width":400,"height":454,"alt":"Young Chang Y 152, πιάνο με ουρά, σε ουδέτερο φόντο","sourceSize":[400,454]}],"pdf":null,"order":26,"name":"Young Chang Y 152","summary":["Το Y 152 υπόσχεται την καλύτερη δυνατή χημεία ανάμεσα σε όργανο και πιανίστα.","Σε αυτό το πιάνο με ουρά συνδυάζονται κομψά η τέχνη της χειροτεχνίας και η ομορφιά. Με προσεκτικά κατασκευασμένο μηχανισμό και πλήκτρα ζυγισμένα ένα προς ένα, ανταποκρίνεται άμεσα στη μουσική έμπνευση του καλλιτέχνη."],"availability":"stock","availabilityLabel":"Στην έκθεση"},{"id":"new-26","slug":"young-chang-y-175","url":"/pianos/new/young-chang-y-175/","detailPage":"piano.html?model=young-chang-y-175","manufacturer":"Young Chang","manufacturerSlug":"young-chang","model":"Y 175","type":"grand","typeLabel":"Πιάνο με ουρά","category":"Κλασικό πιάνο","sizeCm":175,"description":["Η αξιοπρόσεκτη δύναμη και όψη του Y-175 της σειράς Professional Artist θα ενισχύσει οποιοδήποτε στούντιο, σκήνη, ή σπίτι με έναν υψηλότερου επιπέδου ενθουσιασμού.","Το πάθος, η υπερηφάνεια και η προσοχή στη λεπτομέρεια της Young Chang οδήγησαν στη δημιουργία αυτού του πραγματικά παγκοσμίας κλάσης οργάνου. Η επιμονή της Young Chang για τίποτα λιγότερο από την τελειότητα στην ηχητική,στο άγγιγμα και στην ομορφιά κάνει αυτό το κομψά επεξεργασμένο βασιλοπρεπές επαγγελματικό πιάνο με ουρά ένα όνειρο που γίνετε πραγματικότητα."],"additional":["Κλασικό πιάνο","ΜΕΓΕΘΟΣ: 175 x 148 x 102","ΣΤΥΛ: Professional Grand","ΤΕΛΕΙΩΜΑ: Ebony Polish"],"facts":[{"label":"Μέγεθος","value":"175 x 148 x 102"},{"label":"Στυλ","value":"Professional Grand"},{"label":"Τελείωμα","value":"Ebony Polish"}],"drawing":[],"finishes":[],"specModel":null,"specs":[{"label":"Τύπος","value":"Πιάνο με ουρά"},{"label":"Μέγεθος","value":"175 × 148 × 102 cm"},{"label":"Στυλ","value":"Professional Grand"},{"label":"Τελείωμα","value":"Μαύρο γυαλιστερό (Ebony Polish)"}],"images":[{"src":"assets/photos/pianos/new/young-chang-y-175.jpg","width":400,"height":471,"alt":"Young Chang Y 175, πιάνο με ουρά, σε ουδέτερο φόντο","sourceSize":[400,471]}],"pdf":null,"order":27,"name":"Young Chang Y 175","summary":["Η δύναμη και η παρουσία του Y 175, από τη σειρά Professional Artist, δίνουν νέα ένταση σε κάθε στούντιο, σκηνή ή σπίτι."],"body":["Το πάθος και η προσοχή της Young Chang στη λεπτομέρεια οδήγησαν σε ένα όργανο παγκόσμιας κλάσης. Η επιμονή στην τελειότητα στον ήχο, στο άγγιγμα και στην εμφάνιση κάνει αυτό το κομψό επαγγελματικό πιάνο με ουρά ένα όνειρο που γίνεται πραγματικότητα."],"availability":"order","availabilityLabel":"Κατόπιν παραγγελίας"},{"id":"new-25","slug":"young-chang-y-185","url":"/pianos/new/young-chang-y-185/","detailPage":"piano.html?model=young-chang-y-185","manufacturer":"Young Chang","manufacturerSlug":"young-chang","model":"Y 185","type":"grand","typeLabel":"Πιάνο με ουρά","category":"Κλασικό πιάνο","sizeCm":185,"description":["Είτε η αναζήτηση μουσικής είναι ένα επάγγελμα, ένα πάθος, ή και τα δύο για σας, το Y-185 θα καλύψει σε μέγιστο βαθμό τις απαιτήσεις σας για διάκριση.","Κάτω από το αυστηρό βλέμα της Young Chang, καμία λεπτομέρεια από αυτή τη βασιλοπρεπή σειρά πιάνων δεν ξεφεύγει από τον έλεγχο. Το αποτέλεσμα είναι ένας απολαυστικά θερμός τόνος, μια λεπτή ανταπόκριση στην αφή και μια αληθινά εντυπωσιακή δύναμη. Η κομψή καμπίνα του και η απαράμιλλη λεπτομέρεια τοποθετεί το Y-185 στο κέντρο της προσοχής. Ακόμα και όταν δεν παίζεται..."],"additional":["Κλασικό πιάνο","ΜΕΓΕΘΟΣ: 185 x 151 x 101","ΣΤΥΛ: Professional Grand","ΤΕΛΕΙΩΜΑ:Ebony Polish"],"facts":[{"label":"Μέγεθος","value":"185 x 151 x 101"},{"label":"Στυλ","value":"Professional Grand"},{"label":"Τελείωμα","value":"Ebony Polish"}],"drawing":[],"finishes":[],"specModel":null,"specs":[{"label":"Τύπος","value":"Πιάνο με ουρά"},{"label":"Μέγεθος","value":"185 × 151 × 101 cm"},{"label":"Στυλ","value":"Professional Grand"},{"label":"Τελείωμα","value":"Μαύρο γυαλιστερό (Ebony Polish)"}],"images":[{"src":"assets/photos/pianos/new/young-chang-y-185.jpg","width":400,"height":473,"alt":"Young Chang Y 185, πιάνο με ουρά, σε ουδέτερο φόντο","sourceSize":[400,473]}],"pdf":null,"order":28,"name":"Young Chang Y 185","summary":["Είτε η μουσική είναι για εσάς επάγγελμα, πάθος ή και τα δύο, το Y 185 ανταποκρίνεται στο έπακρο στις απαιτήσεις σας."],"body":["Υπό το αυστηρό βλέμμα της Young Chang, καμία λεπτομέρεια αυτής της σειράς δεν ξεφεύγει από τον έλεγχο. Το αποτέλεσμα είναι ένας θερμός τόνος, λεπτή ανταπόκριση στην αφή και εντυπωσιακή δύναμη.","Η κομψή καμπίνα και η προσεγμένη λεπτομέρεια τραβούν την προσοχή, ακόμη κι όταν το πιάνο δεν παίζεται."],"availability":"order","availabilityLabel":"Κατόπιν παραγγελίας"}];
